import { Controller, Get, Post, Body, Query, UseGuards, Request } from '@nestjs/common';
import { WalletService } from './wallet.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';

@Controller('wallet')
@UseGuards(JwtAuthGuard)
export class WalletController {
  constructor(private readonly walletService: WalletService) {}

  @Get('me')
  async getMyWallet(@Request() req) {
    const userId = req.user.id;
    const balance = await this.walletService.getBalance(userId);
    return { balance };
  }

  @Get('me/transactions')
  async getMyTransactions(
    @Request() req,
    @Query('page') page: number = 1,
    @Query('limit') limit: number = 10,
    @Query('type') type?: string
  ) {
    const userId = req.user.id;
    return this.walletService.getTransactions(userId, page, limit, type);
  }

  @Post('me/credit')
  async creditWallet(
    @Request() req,
    @Body() creditDto: { amount: number; description: string }
  ) {
    const userId = req.user.id;
    return this.walletService.credit(userId, creditDto.amount, creditDto.description);
  }

  @Post('me/debit')
  async debitWallet(
    @Request() req,
    @Body() debitDto: { amount: number; description: string }
  ) {
    const userId = req.user.id;
    return this.walletService.debit(userId, debitDto.amount, debitDto.description);
  }
}
